const CSS = "\n  /* ============================================================\n     CardPing — Universal scanner → clean lead  (v3)\n     popl-style: a row of SIX real input objects, side by side,\n     each flowing into a single resolving lead card.\n     Auto-cycles with zero interaction; never blank.\n     Forced-dark, single terracotta accent. Self-contained.\n     Scoped under .cp-uscan so it ports cleanly into React.\n     ============================================================ */\n\n  .cp-uscan {\n    --ground:      #0a0a0a;\n    --surface:     #141414;\n    --surface-2:   #191919;\n    --hair:        rgba(255, 255, 255, 0.08);\n    --hair-2:      rgba(255, 255, 255, 0.14);\n    --text:        #ededed;\n    --muted:       #a1a1a1;\n\n    --acc:         #c2703f;\n    --acc-fill:    rgba(194, 112, 63, 0.14);\n    --acc-line:    rgba(194, 112, 63, 0.35);\n    --acc-glow:    #d1743f;\n\n    --paper:       #f6f4ee;\n    --paper-ink:   #221e19;\n\n    /* tiny recognisable brand marks, only inside the QR objects */\n    --wa:   #25d366;\n    --tg:   #2aabee;\n    --li:   #0a66c2;\n\n    --font-sans: \"Geist\", system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n    --font-mono: \"Geist Mono\", ui-monospace, \"SF Mono\", Menlo, Consolas, monospace;\n    --font-deva: \"Noto Sans Devanagari\", \"Geist\", system-ui, sans-serif;\n\n    --radius: 16px;\n    --ease:   cubic-bezier(0.22, 0.61, 0.36, 1);\n    --per:    4200ms; /* per-input dwell — matches JS CYCLE */\n\n    box-sizing: border-box;\n    color: var(--text);\n    font-family: var(--font-sans);\n    -webkit-font-smoothing: antialiased;\n    text-rendering: optimizeLegibility;\n  }\n\n\n  .cp-uscan, .cp-uscan *, .cp-uscan *::before, .cp-uscan *::after { box-sizing: border-box; }\n\n\n  .cp-uscan .u-section {\n    position: relative;\n    width: 100%;\n    background: var(--ground);\n    padding: clamp(56px, 8vw, 104px) 1.25rem;\n    overflow: hidden;\n  }\n\n\n  /* the single permitted terracotta glow */\n  .cp-uscan .u-section::before {\n    content: \"\";\n    position: absolute;\n    top: 8%;\n    left: 50%;\n    width: min(980px, 94%);\n    height: 560px;\n    transform: translateX(-50%);\n    background: radial-gradient(ellipse at center, rgba(194, 112, 63, 0.15), rgba(194, 112, 63, 0) 68%);\n    filter: blur(14px);\n    pointer-events: none;\n    z-index: 0;\n  }\n\n\n  .cp-uscan .u-wrap {\n    position: relative;\n    z-index: 1;\n    max-width: 1120px;\n    margin: 0 auto;\n  }\n\n\n  /* ---------- header ---------- */\n  .cp-uscan .u-eyebrow {\n    display: inline-flex;\n    align-items: center;\n    gap: 8px;\n    margin: 0 0 18px;\n    font-family: var(--font-mono);\n    font-size: 12px;\n    font-weight: 500;\n    letter-spacing: 0.22em;\n    text-transform: uppercase;\n    color: var(--acc);\n  }\n\n  .cp-uscan .u-eyebrow::before {\n    content: \"\";\n    width: 6px; height: 6px;\n    border-radius: 2px;\n    background: var(--acc-glow);\n    box-shadow: 0 0 10px rgba(209, 116, 63, 0.7);\n  }\n\n\n  .cp-uscan .u-heading {\n    margin: 0 0 16px;\n    max-width: 18ch;\n    font-size: clamp(30px, 5vw, 52px);\n    line-height: 1.04;\n    letter-spacing: -0.022em;\n    font-weight: 600;\n    background: linear-gradient(176deg, #f5f5f5 24%, #8b8b8b);\n    -webkit-background-clip: text;\n    background-clip: text;\n    color: transparent;\n  }\n\n\n  .cp-uscan .u-lede {\n    margin: 0 0 clamp(34px, 4.5vw, 54px);\n    max-width: 66ch;\n    font-size: clamp(15px, 1.6vw, 18px);\n    line-height: 1.6;\n    color: var(--muted);\n  }\n\n\n  /* ============================================================\n     STAGE — inputs row  →  flow  →  lead card\n     ============================================================ */\n  .cp-uscan .u-stage { position: relative; }\n\n\n  /* ---------- the row of six input objects ---------- */\n  .cp-uscan .inputs-rail {\n    display: grid;\n    grid-template-columns: repeat(6, minmax(0, 1fr));\n    gap: clamp(8px, 1.3vw, 18px);\n    max-width: 1000px;\n    margin: 0 auto;\n  }\n\n\n  .cp-uscan .obj {\n    -webkit-appearance: none;\n    appearance: none;\n    margin: 0;\n    border: 0;\n    background: transparent;\n    padding: 4px 0 0;\n    font: inherit;\n    color: inherit;\n    cursor: pointer;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 11px;\n    min-width: 0;\n    -webkit-tap-highlight-color: transparent;\n    opacity: 0.72;\n    transition: opacity 0.4s var(--ease), transform 0.4s var(--ease);\n  }\n\n  .cp-uscan .obj:hover { opacity: 0.92; }\n\n  .cp-uscan .obj.is-active { opacity: 1; }\n\n  .cp-uscan .obj:focus-visible { outline: none; }\n\n  .cp-uscan .obj:focus-visible .obj-vis {\n    outline: 2px solid var(--acc-glow);\n    outline-offset: 4px;\n  }\n\n\n  /* the fixed visual band each object is centred within */\n  .cp-uscan .obj-vis {\n    position: relative;\n    width: 100%;\n    height: clamp(104px, 13vw, 140px);\n    border-radius: 14px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    transition: transform 0.45s var(--ease);\n  }\n\n  .cp-uscan .obj.is-active .obj-vis { transform: translateY(-2px) scale(1.015); }\n\n\n  /* active-object ring + terracotta glow */\n  .cp-uscan .obj-vis::after {\n    content: \"\";\n    position: absolute;\n    inset: -7px;\n    border-radius: 17px;\n    border: 1.5px solid transparent;\n    box-shadow: none;\n    opacity: 0;\n    transition: opacity 0.4s var(--ease);\n    pointer-events: none;\n  }\n\n  .cp-uscan .obj.is-active .obj-vis::after {\n    opacity: 1;\n    border-color: var(--acc-line);\n    box-shadow:\n      0 0 0 1px rgba(194,112,63,0.14),\n      0 16px 40px -14px rgba(209,116,63,0.55),\n      0 0 26px -4px rgba(209,116,63,0.30);\n  }\n\n\n  .cp-uscan .obj-cap {\n    font-family: var(--font-mono);\n    font-size: 10.5px;\n    letter-spacing: 0.08em;\n    color: var(--muted);\n    text-align: center;\n    line-height: 1.2;\n    transition: color 0.35s var(--ease);\n    white-space: nowrap;\n  }\n\n  .cp-uscan .obj.is-active .obj-cap { color: var(--acc-glow); }\n\n\n  /* --- scan FX overlay on the active object --- */\n  .cp-uscan .obj .fx { position: absolute; inset: -3px; pointer-events: none; z-index: 4; }\n\n  .cp-uscan .obj .bk {\n    position: absolute;\n    width: 15px; height: 15px;\n    border: 2px solid var(--acc);\n    opacity: 0;\n    filter: drop-shadow(0 0 6px rgba(209,116,63,0.55));\n  }\n\n  .cp-uscan .obj .bk.tl { top: 0; left: 0; border-right: 0; border-bottom: 0; border-top-left-radius: 5px; }\n\n  .cp-uscan .obj .bk.tr { top: 0; right: 0; border-left: 0; border-bottom: 0; border-top-right-radius: 5px; }\n\n  .cp-uscan .obj .bk.bl { bottom: 0; left: 0; border-right: 0; border-top: 0; border-bottom-left-radius: 5px; }\n\n  .cp-uscan .obj .bk.br { bottom: 0; right: 0; border-left: 0; border-top: 0; border-bottom-right-radius: 5px; }\n\n  .cp-uscan .obj .sweep {\n    position: absolute;\n    left: 4px; right: 4px; top: 4px;\n    height: 46%;\n    border-radius: 8px;\n    opacity: 0;\n    background: linear-gradient(180deg,\n      rgba(209,116,63,0) 0%,\n      rgba(209,116,63,0.10) 60%,\n      rgba(209,116,63,0.32) 96%,\n      rgba(209,116,63,0) 100%);\n    border-bottom: 1.5px solid var(--acc-glow);\n    box-shadow: 0 6px 22px -2px rgba(209,116,63,0.5);\n  }\n\n\n  /* ---------- REALISTIC OBJECTS — each recognisably real & distinct ---------- */\n\n  /* shared QR svg fill helper */\n  .cp-uscan .qsvg { display: block; width: 100%; height: 100%; }\n\n  .cp-uscan .qbox { display: block; position: relative; width: 100%; aspect-ratio: 1 / 1; }\n\n\n  /* structural normalisation — these are <span>s, force block/flex sizing so\n     widths + aspect-ratios apply and flex min-content never inflates them */\n  .cp-uscan .photo-card, .cp-uscan .poster, .cp-uscan .li-card,\n  .cp-uscan .wa-frame, .cp-uscan .tg-tile, .cp-uscan .badge-unit {\n    flex: 0 0 auto; min-width: 0;\n  }\n\n  .cp-uscan .poster-qr, .cp-uscan .poster-deva, .cp-uscan .poster-kicker,\n  .cp-uscan .li-top, .cp-uscan .li-meta, .cp-uscan .li-qrwrap,\n  .cp-uscan .li-name, .cp-uscan .li-role,\n  .cp-uscan .wa-card, .cp-uscan .tg-handle,\n  .cp-uscan .badge-fan, .cp-uscan .tbadge, .cp-uscan .tb-head,\n  .cp-uscan .tb-body, .cp-uscan .tb-name, .cp-uscan .tb-co,\n  .cp-uscan .tb-event, .cp-uscan .tb-line {\n    display: block;\n  }\n\n\n  /* centre brand marks (only recognisable glyphs allowed inside QRs) */\n  .cp-uscan .li-badge, .cp-uscan .wa-badge, .cp-uscan .tg-badge {\n    position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);\n  }\n\n  .cp-uscan .li-badge {\n    width: 30%; aspect-ratio: 1 / 1; border-radius: 4px;\n    background: var(--li); color: #fff;\n    display: flex; align-items: center; justify-content: center;\n    font-size: 9px; font-weight: 700; letter-spacing: -0.07em; line-height: 1;\n    box-shadow: 0 0 0 2px #fff, 0 1px 3px rgba(0,0,0,0.25);\n  }\n\n  .cp-uscan .wa-badge { width: 32%; aspect-ratio: 1 / 1; border-radius: 50%; box-shadow: 0 0 0 2px #fff; }\n\n  .cp-uscan .wa-badge svg { display: block; width: 100%; height: 100%; border-radius: 50%; }\n\n  .cp-uscan .tg-badge {\n    width: 32%; aspect-ratio: 1 / 1; border-radius: 50%; background: #fff;\n    display: flex; align-items: center; justify-content: center;\n    box-shadow: 0 2px 6px -1px rgba(0,0,0,0.4);\n  }\n\n  .cp-uscan .tg-badge svg { display: block; width: 66%; height: 66%; }\n\n\n  /* --- 0 · visiting card — the REAL photographed card --- */\n  .cp-uscan .o-card { width: 100%; }\n\n  .cp-uscan .photo-card {\n    position: relative;\n    width: clamp(108px, 14vw, 138px);\n    aspect-ratio: 460 / 356;\n    transform: rotate(-3.5deg);\n    border-radius: 9px;\n    padding: 4px;                         /* white photo lip */\n    background: linear-gradient(160deg, #fdfdfb, #efece4);\n    box-shadow:\n      0 1px 0 rgba(255,255,255,0.7) inset,\n      0 15px 28px -12px rgba(0,0,0,0.85);\n  }\n\n  .cp-uscan .photo-card img {\n    display: block; width: 100%; height: 100%;\n    object-fit: cover; border-radius: 6px;\n  }\n\n  .cp-uscan .photo-card::after {           /* inner shadow — reads as photographed */\n    content: \"\"; position: absolute; inset: 4px;\n    border-radius: 6px; pointer-events: none;\n    box-shadow: inset 0 0 0 1px rgba(0,0,0,0.14), inset 0 3px 13px rgba(0,0,0,0.34);\n  }\n\n\n  /* --- 1 · website QR — printed table-tent / flyer --- */\n  .cp-uscan .poster {\n    position: relative;\n    width: clamp(84px, 10.6vw, 104px);\n    transform: rotate(2deg);\n    background: linear-gradient(158deg, #fbf9f3 0%, #efe9dc 100%);\n    border-radius: 9px;\n    padding: 7px 7px 6px;\n    box-shadow: 0 1px 0 rgba(255,255,255,0.6) inset, 0 13px 24px -12px rgba(0,0,0,0.78);\n    display: flex; flex-direction: column; align-items: center; gap: 4px;\n  }\n\n  .cp-uscan .poster::after {               /* soft ground shadow — a standing tent */\n    content: \"\"; position: absolute; left: 10%; right: 10%; bottom: -6px; height: 7px;\n    background: radial-gradient(ellipse at center, rgba(0,0,0,0.32), rgba(0,0,0,0) 70%);\n    filter: blur(1px);\n  }\n\n  .cp-uscan .poster-kicker {\n    font-family: var(--font-mono); font-size: 5.2px; letter-spacing: 0.16em;\n    text-transform: uppercase; color: #8a7f6c;\n  }\n\n  .cp-uscan .poster-deva {\n    font-family: var(--font-deva); font-size: 8px; font-weight: 700;\n    color: #35301f; line-height: 1; letter-spacing: -0.01em;\n  }\n\n  .cp-uscan .poster-qr {\n    width: 100%; aspect-ratio: 1 / 1;\n    background: #fff; border-radius: 3px; padding: 2px; margin-top: 1px;\n  }\n\n  .cp-uscan .poster-url {\n    display: flex; align-items: center; gap: 3px;\n    font-size: 6.4px; font-weight: 600; color: #4a4234; letter-spacing: 0.01em;\n  }\n\n  .cp-uscan .poster-url svg { width: 6px; height: 6px; color: #9a5228; flex: none; }\n\n\n  /* --- 2 · LinkedIn profile QR card --- */\n  .cp-uscan .li-card {\n    position: relative;\n    width: clamp(90px, 11vw, 102px);\n    transform: rotate(-2deg);\n    background: #fff; color: #1a1a1a;\n    border-radius: 10px; overflow: hidden;\n    box-shadow: 0 1px 0 rgba(255,255,255,0.5) inset, 0 13px 24px -12px rgba(0,0,0,0.78);\n  }\n\n  .cp-uscan .li-top { height: 4px; background: var(--li); }\n\n  .cp-uscan .li-head { display: flex; align-items: center; gap: 4px; padding: 5px 6px 2px; }\n\n  .cp-uscan .li-av {\n    flex: none; width: 15px; height: 15px; border-radius: 50%;\n    background: linear-gradient(150deg, #4f9fe0, #0a66c2); color: #fff;\n    display: flex; align-items: center; justify-content: center;\n    font-size: 7px; font-weight: 600;\n  }\n\n  .cp-uscan .li-meta { min-width: 0; flex: 1; }\n\n  .cp-uscan .li-name { font-size: 7.6px; font-weight: 700; color: #101418; line-height: 1.05; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n\n  .cp-uscan .li-role { font-size: 5.5px; color: #5b6b7a; margin-top: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n\n  .cp-uscan .li-in {\n    flex: none; width: 12px; height: 12px; border-radius: 2.5px;\n    background: var(--li); color: #fff; font-size: 8px; font-weight: 700;\n    letter-spacing: -0.08em; line-height: 1;\n    display: flex; align-items: center; justify-content: center;\n  }\n\n  .cp-uscan .li-qrwrap { padding: 2px 12px 9px; }\n\n\n  /* --- 3 · WhatsApp \"My QR code\" --- */\n  .cp-uscan .wa-frame {\n    position: relative;\n    width: clamp(88px, 11vw, 106px);\n    transform: rotate(2deg);\n    background: linear-gradient(160deg, #2bd06a 0%, #12b356 100%);\n    border-radius: 12px; padding: 7px;\n    box-shadow: 0 1px 0 rgba(255,255,255,0.22) inset, 0 13px 24px -12px rgba(0,0,0,0.78);\n    display: flex; flex-direction: column; align-items: center; gap: 5px;\n  }\n\n  .cp-uscan .wa-av {\n    width: 20px; height: 20px; border-radius: 50%;\n    background: linear-gradient(150deg, #eafaf0, #cdead8);\n    border: 1.5px solid #fff; color: #0b7a43;\n    display: flex; align-items: center; justify-content: center;\n    font-size: 8px; font-weight: 700; margin-top: 1px;\n    box-shadow: 0 2px 5px -2px rgba(0,0,0,0.45);\n  }\n\n  .cp-uscan .wa-card { width: 100%; background: #fff; border-radius: 8px; padding: 6px; }\n\n\n  /* --- 4 · Telegram QR — blue tile, white round dots, plane centre --- */\n  .cp-uscan .tg-tile {\n    position: relative;\n    width: clamp(84px, 10.6vw, 102px);\n    transform: rotate(-2.5deg);\n    background: linear-gradient(160deg, #2aabee 0%, #229ed9 100%);\n    border-radius: 14px; padding: 9px 9px 5px;\n    box-shadow: 0 1px 0 rgba(255,255,255,0.28) inset, 0 14px 26px -12px rgba(0,0,0,0.82);\n    display: flex; flex-direction: column; align-items: center; gap: 3px;\n  }\n\n  .cp-uscan .tg-handle {\n    font-family: var(--font-mono); font-size: 6.4px; font-weight: 500;\n    color: #eaf7ff; letter-spacing: 0.03em;\n  }\n\n\n  /* --- 5 · event badge — fanned stack of three tiers on a lanyard --- */\n  .cp-uscan .o-badge .badge-unit {\n    display: flex; flex-direction: column; align-items: center;\n    width: clamp(92px, 11.6vw, 112px);\n  }\n\n  .cp-uscan .lanyard { position: relative; width: 100%; height: 24px; z-index: 5; }\n\n  .cp-uscan .strap {\n    position: absolute; bottom: -1px; left: 50%;\n    width: 9px; height: 34px; border-radius: 2px 2px 0 0;\n    background: linear-gradient(180deg, #7c4a2c 0%, var(--acc) 55%, #a85c30 100%);\n    transform-origin: bottom center;\n    box-shadow: inset 0 0 0 1px rgba(0,0,0,0.12);\n  }\n\n  .cp-uscan .strap.l { transform: translateX(-50%) rotate(-19deg); }\n\n  .cp-uscan .strap.r { transform: translateX(-50%) rotate(19deg); }\n\n  .cp-uscan .clip {\n    position: absolute; left: 50%; bottom: -6px; transform: translateX(-50%);\n    width: 22px; height: 11px; border-radius: 3px;\n    background: linear-gradient(180deg, #e0e0e0, #9a9a9a);\n    box-shadow: 0 2px 5px -2px rgba(0,0,0,0.7); z-index: 2;\n  }\n\n  .cp-uscan .clip::after {\n    content: \"\"; position: absolute; left: 50%; top: 3px; transform: translateX(-50%);\n    width: 10px; height: 3px; border-radius: 2px; background: rgba(0,0,0,0.35);\n  }\n\n  .cp-uscan .badge-fan {\n    position: relative;\n    width: clamp(60px, 7.5vw, 72px);\n    height: clamp(66px, 8.2vw, 78px);\n    margin-top: 1px;\n  }\n\n  .cp-uscan .tbadge {\n    position: absolute; top: 0; left: 50%; width: 100%;\n    border-radius: 8px; overflow: hidden;\n    background: #f4f2ec; color: #221e19;\n    box-shadow: 0 10px 20px -10px rgba(0,0,0,0.82), 0 0 0 1px rgba(0,0,0,0.06);\n    transform-origin: 50% 6px;\n  }\n\n  /* fan: VIP front-centre-lower; the two tiers splay up-and-out so their\n     coloured headers sit ABOVE the VIP badge and read in full */\n  .cp-uscan .tbadge.t-att { transform: translate(calc(-50% - 19px), 0) rotate(-9deg); z-index: 1; }\n\n  .cp-uscan .tbadge.t-exh { transform: translate(calc(-50% + 19px), 4px) rotate(9deg); z-index: 2; }\n\n  .cp-uscan .tbadge.t-vip { transform: translate(-50%, 20px) rotate(0deg); z-index: 3; }\n\n  .cp-uscan .tb-head {\n    padding: 3px 4px; color: #fff; text-align: center;\n    font-size: 5.4px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase;\n    white-space: nowrap;\n  }\n\n  .cp-uscan .t-att .tb-head { background: linear-gradient(120deg, #7c8698, #545f70); }\n\n  .cp-uscan .t-exh .tb-head { background: linear-gradient(120deg, #21a58c, #12796a); }\n\n  .cp-uscan .t-vip .tb-head { background: linear-gradient(120deg, #3a352b, #201e19); color: #ecc677; }\n\n  .cp-uscan .tb-body { padding: 4px 5px 6px; text-align: center; }\n\n  .cp-uscan .tb-name { font-size: 7px; font-weight: 700; color: #221e19; line-height: 1.05; }\n\n  .cp-uscan .tb-co   { font-size: 5.2px; color: #7c7160; margin-top: 1px; }\n\n  .cp-uscan .tb-event { font-size: 4.6px; color: #9a9184; margin-top: 3px; letter-spacing: 0.04em; }\n\n  .cp-uscan .tb-line { height: 2.4px; border-radius: 2px; background: #d9d4c8; margin: 3px 3px 0; }\n\n  .cp-uscan .tb-line.s2 { width: 62%; margin-left: auto; margin-right: auto; }\n\n\n  /* ============================================================\n     FLOW — converging lines from each object into the lead card\n     ============================================================ */\n  .cp-uscan .flow {\n    position: relative;\n    max-width: 1000px;\n    margin: 0 auto;\n    height: clamp(64px, 8vw, 104px);\n  }\n\n  .cp-uscan .flow svg { display: block; width: 100%; height: 100%; overflow: visible; }\n\n  .cp-uscan .flow-path {\n    fill: none;\n    stroke: var(--hair-2);\n    stroke-width: 1.1;\n    stroke-linecap: round;\n    opacity: 0.5;\n    transition: stroke 0.4s var(--ease), opacity 0.4s var(--ease);\n  }\n\n  .cp-uscan .flow-path.is-active {\n    stroke: var(--acc-line);\n    opacity: 1;\n  }\n\n  /* the bright packet drawing from the active object into the lead */\n  .cp-uscan.playing.is-extract .flow-path.is-active,\n  .cp-uscan.playing.is-resolve .flow-path.is-active {\n    stroke: var(--acc-glow);\n    stroke-width: 1.9;\n    filter: drop-shadow(0 0 4px rgba(209,116,63,0.65));\n    stroke-dasharray: 22 100;\n    animation: cpFlowDraw 1.25s var(--ease) both;\n  }\n\n  .cp-uscan .flow-hit {\n    fill: var(--acc-glow);\n    opacity: 0;\n  }\n\n  .cp-uscan.playing.is-resolve .flow-hit,\n  .cp-uscan.playing.is-hold .flow-hit {\n    animation: cpHit 0.9s var(--ease) both;\n  }\n\n\n  /* mobile-only simple connector (hidden on desktop) */\n  .cp-uscan .flow-mini { display: none; }\n\n\n  /* ============================================================\n     LEAD — a single card; six faces cross-fade in place\n     ============================================================ */\n  .cp-uscan .lead-stack {\n    position: relative;\n    display: grid;\n    max-width: 520px;\n    margin: 0 auto;\n  }\n\n  .cp-uscan .leadface {\n    grid-column: 1;\n    grid-row: 1;\n    background: var(--surface);\n    border: 1px solid var(--hair);\n    border-radius: var(--radius);\n    overflow: hidden;\n    box-shadow: 0 30px 60px -30px rgba(0,0,0,0.8);\n    opacity: 0;\n    visibility: hidden;\n    pointer-events: none;\n    transition: opacity 0.55s var(--ease), visibility 0s linear 0.55s;\n  }\n\n  .cp-uscan .leadface.is-active {\n    opacity: 1;\n    visibility: visible;\n    pointer-events: auto;\n    z-index: 2;\n    transition: opacity 0.55s var(--ease), visibility 0s;\n  }\n\n\n  .cp-uscan .panel-bar {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 10px;\n    padding: 11px 16px;\n    border-bottom: 1px solid var(--hair);\n    background: var(--surface-2);\n  }\n\n  .cp-uscan .pb-label {\n    font-family: var(--font-mono);\n    font-size: 11px;\n    letter-spacing: 0.16em;\n    text-transform: uppercase;\n    color: var(--muted);\n  }\n\n  .cp-uscan .pb-brand { color: var(--acc); }\n\n\n  /* mono status readout */\n  .cp-uscan .lead-status {\n    display: flex; align-items: center; gap: 8px;\n    padding: 10px 16px;\n    border-bottom: 1px solid var(--hair);\n    font-family: var(--font-mono);\n    font-size: 11px;\n    letter-spacing: 0.02em;\n    color: var(--muted);\n    background: rgba(255,255,255,0.012);\n  }\n\n  .cp-uscan .live-dot {\n    width: 7px; height: 7px; border-radius: 50%;\n    background: var(--acc-glow);\n    box-shadow: 0 0 8px rgba(209,116,63,0.8);\n    flex: none;\n    animation: cpLive 1.5s ease-in-out infinite;\n  }\n\n  .cp-uscan .lead-status .s { display: none; }\n\n  .cp-uscan .lead-status .s--done { display: inline; }\n /* base = done */\n\n  .cp-uscan .lead-body { padding: clamp(16px, 3vw, 22px); }\n\n  .cp-uscan .lead-head { display: flex; align-items: center; gap: 14px; margin-bottom: 16px; }\n\n  .cp-uscan .avatar {\n    position: relative;\n    flex: none;\n    width: 50px; height: 50px;\n    border-radius: 50%;\n    display: flex; align-items: center; justify-content: center;\n    background: linear-gradient(150deg, var(--acc-glow), #9d5228);\n    color: #fff; font-weight: 600; font-size: 17px;\n    box-shadow: 0 6px 16px -6px rgba(194,112,63,0.7);\n  }\n\n  .cp-uscan .av-skel {\n    position: absolute; inset: 0;\n    border-radius: 50%;\n    border: 1.5px dashed var(--hair-2);\n    background: var(--surface-2);\n    opacity: 0;\n  }\n\n  .cp-uscan .av-i { position: relative; z-index: 1; }\n\n  .cp-uscan .lead-id { min-width: 0; }\n\n  .cp-uscan .lead-name { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; line-height: 1.15; }\n\n  .cp-uscan .lead-sub {\n    margin-top: 3px;\n    font-size: 13.5px; color: var(--muted);\n    display: flex; flex-wrap: wrap; align-items: center; gap: 6px;\n  }\n\n  .cp-uscan .lead-sub .dot { color: var(--hair-2); }\n\n\n  .cp-uscan .lead-rows {\n    display: grid; gap: 2px;\n    border-top: 1px solid var(--hair);\n    padding-top: 12px;\n  }\n\n  .cp-uscan .row {\n    display: grid;\n    grid-template-columns: 86px 1fr auto;\n    align-items: center;\n    gap: 12px;\n    padding: 8px 2px;\n  }\n\n  .cp-uscan .row + .row { border-top: 1px solid var(--hair); }\n\n  .cp-uscan .row-label {\n    font-family: var(--font-mono);\n    font-size: 10.5px; letter-spacing: 0.12em; text-transform: uppercase;\n    color: var(--muted);\n  }\n\n  .cp-uscan .row-val {\n    font-size: 14px; color: var(--text);\n    min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;\n  }\n\n  .cp-uscan .rc {\n    width: 18px; height: 18px; border-radius: 50%;\n    display: inline-flex; align-items: center; justify-content: center;\n    background: var(--acc-fill); color: var(--acc-glow);\n    border: 1px solid var(--acc-line);\n    flex: none;\n  }\n\n\n  .cp-uscan .lead-foot {\n    display: flex; align-items: center; justify-content: space-between;\n    flex-wrap: wrap; gap: 10px;\n    margin-top: 15px; padding-top: 14px;\n    border-top: 1px solid var(--hair);\n  }\n\n  .cp-uscan .ftag {\n    display: inline-flex; align-items: center; gap: 7px;\n    padding: 6px 11px; border-radius: 999px;\n    background: var(--acc-fill); border: 1px solid var(--acc-line);\n    color: var(--text); font-size: 12.5px; font-weight: 500;\n    max-width: 100%;\n  }\n\n  .cp-uscan .ftag .fi { color: var(--acc-glow); display: block; flex: none; }\n\n  .cp-uscan .ftag .gmark { flex: none; border-radius: 4px; display: block; }\n\n  .cp-uscan .added {\n    display: inline-flex; align-items: center; gap: 7px;\n    font-size: 13px; font-weight: 500; color: var(--acc-glow);\n    white-space: nowrap;\n  }\n\n  .cp-uscan .added .badge2 {\n    width: 18px; height: 18px; border-radius: 50%;\n    display: inline-flex; align-items: center; justify-content: center;\n    background: var(--acc); color: #120c07;\n    flex: none;\n  }\n\n\n  .cp-uscan .v { display: inline-block; }\n\n\n  /* closing claim */\n  .cp-uscan .u-claim {\n    margin: clamp(34px, 4.5vw, 52px) auto 0;\n    max-width: 720px;\n    padding: 16px 18px;\n    border-left: 2px solid var(--acc-line);\n    background: linear-gradient(90deg, var(--acc-fill), rgba(194,112,63,0));\n    border-radius: 4px;\n    font-size: clamp(14px, 1.5vw, 16px);\n    line-height: 1.55;\n    color: var(--text);\n    text-align: center;\n  }\n\n  .cp-uscan .u-claim strong { color: var(--acc-glow); font-weight: 600; }\n\n\n  /* ============================================================\n     ANIMATION — classes JS toggles on .cp-uscan drive phases.\n     Base (no .playing) = active face fully resolved, static.\n     ============================================================ */\n  .cp-uscan .v, .cp-uscan .ftag, .cp-uscan .added, .cp-uscan .rc,\n  .cp-uscan .av-i, .cp-uscan .av-skel, .cp-uscan .avatar {\n    transition: opacity 0.35s var(--ease), transform 0.35s var(--ease),\n                background 0.4s var(--ease), box-shadow 0.4s var(--ease);\n  }\n\n  .cp-uscan .obj .bk, .cp-uscan .obj .sweep { opacity: 0; }\n\n\n  /* ---- IDLE (playing, active face, no phase): empty the lead ---- */\n  .cp-uscan.playing .leadface.is-active .v { opacity: 0; transform: translateY(7px); }\n\n  .cp-uscan.playing .leadface.is-active .rc { opacity: 0; transform: scale(0.5); }\n\n  .cp-uscan.playing .leadface.is-active .ftag,\n  .cp-uscan.playing .leadface.is-active .added { opacity: 0; transform: translateY(4px); }\n\n  .cp-uscan.playing .leadface.is-active .av-i { opacity: 0; }\n\n  .cp-uscan.playing .leadface.is-active .av-skel { opacity: 1; }\n\n  .cp-uscan.playing .leadface.is-active .avatar { background: transparent; box-shadow: none; }\n\n  .cp-uscan.playing .leadface.is-active .lead-status .s--done { display: none; }\n\n  .cp-uscan.playing .leadface.is-active .lead-status .s--focus { display: inline; }\n\n\n  /* ---- SCAN — the active object gets brackets + sweep ---- */\n  .cp-uscan.playing.is-scan .obj.is-active .bk { opacity: 1; animation: cpBk 0.4s var(--ease) both; }\n\n  .cp-uscan.playing.is-scan .obj.is-active .sweep { opacity: 1; animation: cpSweep 1.25s var(--ease) both; }\n\n  .cp-uscan.playing.is-scan .leadface.is-active .lead-status .s--focus { display: none; }\n\n  .cp-uscan.playing.is-scan .leadface.is-active .lead-status .s--read { display: inline; }\n\n\n  /* ---- EXTRACT — fields resolve one by one ---- */\n  .cp-uscan.playing.is-extract .leadface.is-active .v {\n    animation: cpReveal 0.5s var(--ease) both;\n    animation-delay: calc(var(--i) * 0.16s);\n  }\n\n  .cp-uscan.playing.is-extract .leadface.is-active .rc {\n    animation: cpPop 0.4s var(--ease) both;\n    animation-delay: calc(var(--i) * 0.16s + 0.22s);\n  }\n\n\n  /* ---- RESOLVE — avatar + source + added ---- */\n  .cp-uscan.playing.is-resolve .obj.is-active .sweep,\n  .cp-uscan.playing.is-resolve .obj.is-active .bk { opacity: 0; }\n\n  .cp-uscan.playing.is-resolve .leadface.is-active .av-skel { opacity: 0; }\n\n  .cp-uscan.playing.is-resolve .leadface.is-active .avatar {\n    background: linear-gradient(150deg, var(--acc-glow), #9d5228);\n    box-shadow: 0 6px 16px -6px rgba(194,112,63,0.7);\n  }\n\n  .cp-uscan.playing.is-resolve .leadface.is-active .av-i { animation: cpPop 0.5s var(--ease) both; opacity: 1; }\n\n  .cp-uscan.playing.is-resolve .leadface.is-active .ftag { animation: cpReveal 0.5s var(--ease) both; }\n\n  .cp-uscan.playing.is-resolve .leadface.is-active .added { animation: cpReveal 0.5s 0.16s var(--ease) both; }\n\n  .cp-uscan.playing.is-resolve .leadface.is-active .lead-status .s--read { display: none; }\n\n  .cp-uscan.playing.is-resolve .leadface.is-active .lead-status .s--done { display: inline; }\n\n\n  /* ---- HOLD ---- */\n  .cp-uscan.playing.is-hold .leadface.is-active .added .badge2 { animation: cpBadge 1.4s var(--ease) 1; }\n\n\n  @keyframes cpSweep {\n    0%   { transform: translateY(-10%); opacity: 0; }\n    12%  { opacity: 1; }\n    88%  { opacity: 1; }\n    100% { transform: translateY(190%); opacity: 0; }\n  }\n\n  @keyframes cpBk { from { opacity: 0; transform: scale(1.4); } to { opacity: 1; transform: scale(1); } }\n\n  @keyframes cpReveal {\n    0%   { opacity: 0; transform: translateY(7px); text-shadow: 0 0 12px rgba(209,116,63,0); }\n    55%  { opacity: 1; text-shadow: 0 0 13px rgba(209,116,63,0.5); }\n    100% { opacity: 1; transform: translateY(0); text-shadow: 0 0 0 rgba(209,116,63,0); }\n  }\n\n  @keyframes cpPop {\n    0%   { opacity: 0; transform: scale(0.5); }\n    60%  { opacity: 1; transform: scale(1.12); }\n    100% { opacity: 1; transform: scale(1); }\n  }\n\n  @keyframes cpLive { 0%,100% { opacity: 1; } 50% { opacity: 0.35; } }\n\n  @keyframes cpBadge {\n    0%   { box-shadow: 0 0 0 0 rgba(209,116,63,0.55); }\n    100% { box-shadow: 0 0 0 12px rgba(209,116,63,0); }\n  }\n\n  @keyframes cpFlowDraw {\n    0%   { stroke-dashoffset: 122; }\n    100% { stroke-dashoffset: 22; }\n  }\n\n  @keyframes cpHit {\n    0%   { opacity: 0; transform: scale(0.4); transform-box: fill-box; transform-origin: center; }\n    40%  { opacity: 1; transform: scale(1.15); transform-box: fill-box; transform-origin: center; }\n    100% { opacity: 0; transform: scale(1); transform-box: fill-box; transform-origin: center; }\n  }\n\n\n  /* ============================================================\n     RESPONSIVE\n     ============================================================ */\n  @media (max-width: 780px) {\n    .cp-uscan .inputs-rail {\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n      gap: 14px 10px;\n      max-width: 420px;\n    }\n    /* desktop converging flow is meaningless once objects wrap: swap it */\n    .cp-uscan .flow { display: none; }\n    .cp-uscan .flow-mini {\n      display: block;\n      position: relative;\n      width: 2px;\n      height: clamp(34px, 9vw, 52px);\n      margin: 18px auto 16px;\n      background: linear-gradient(180deg, var(--acc-line), rgba(194,112,63,0.05));\n      border-radius: 2px;\n      overflow: visible;\n    }\n    .cp-uscan .flow-mini::before {\n      content: \"\";\n      position: absolute;\n      left: 50%; bottom: -6px; transform: translateX(-50%) rotate(45deg);\n      width: 8px; height: 8px;\n      border-right: 2px solid var(--acc-glow);\n      border-bottom: 2px solid var(--acc-glow);\n    }\n    .cp-uscan .flow-mini .pkt {\n      position: absolute;\n      left: 50%; top: 0; transform: translateX(-50%);\n      width: 7px; height: 7px; border-radius: 50%;\n      background: var(--acc-glow);\n      box-shadow: 0 0 10px rgba(209,116,63,0.9);\n      opacity: 0;\n    }\n    .cp-uscan.playing.is-extract .flow-mini .pkt,\n    .cp-uscan.playing.is-resolve .flow-mini .pkt {\n      animation: cpPkt 1.2s var(--ease) both;\n    }\n    @keyframes cpPkt {\n      0%   { top: 0; opacity: 0; }\n      20%  { opacity: 1; }\n      100% { top: 100%; opacity: 0.9; }\n    }\n    .cp-uscan .obj-vis { height: clamp(100px, 28vw, 130px); }\n    /* badge unit is the tallest object — keep it inside its band on narrow screens */\n    .cp-uscan .o-badge .badge-unit { transform: scale(0.9); transform-origin: center top; }\n    .cp-uscan .o-qr2 .li-card { transform: rotate(-2deg) scale(0.94); transform-origin: center; }\n    .cp-uscan .o-qr3 .wa-frame { transform: rotate(2deg) scale(0.94); transform-origin: center; }\n  }\n\n\n  @media (max-width: 420px) {\n    .cp-uscan .inputs-rail { gap: 12px 8px; }\n    .cp-uscan .obj { gap: 8px; }\n    .cp-uscan .obj-cap { font-size: 9.5px; letter-spacing: 0.04em; }\n    .cp-uscan .row { grid-template-columns: 72px 1fr auto; gap: 8px; }\n    .cp-uscan .row-val { font-size: 13px; }\n    .cp-uscan .lead-name { font-size: 18px; }\n  }\n\n\n  /* ============================================================\n     REDUCED MOTION — JS bails; base (face 0) shows static.\n     ============================================================ */\n  @media (prefers-reduced-motion: reduce) {\n    .cp-uscan *, .cp-uscan *::before, .cp-uscan *::after {\n      animation: none !important;\n      transition: none !important;\n    }\n    .cp-uscan .live-dot { opacity: 0.9; }\n  }";
