const SCRIPT = "\n  (function () {\n    var root = document.querySelector(\".cp-uscan\");\n    if (!root) return;\n    var stage  = root.querySelector(\"#cpUStage\");\n    var objs   = Array.prototype.slice.call(root.querySelectorAll(\".obj\"));\n    var faces  = Array.prototype.slice.call(root.querySelectorAll(\".leadface\"));\n    var paths  = Array.prototype.slice.call(root.querySelectorAll(\".flow-path\"));\n    var N = objs.length;\n\n    var CYCLE = 4200;                 // per-input dwell (matches --per)\n    var PH = { scan: 360, extract: 1500, resolve: 2560, hold: 3480 };\n\n    var timers = [];\n    function clearTimers() { for (var i = 0; i < timers.length; i++) clearTimeout(timers[i]); timers = []; }\n    function at(ms, fn) { timers.push(setTimeout(fn, ms)); }\n\n    var current = 0;\n\n    function setActive(i) {\n      current = i;\n      root.setAttribute(\"data-active\", i);\n      for (var s = 0; s < N; s++) {\n        var on = (s === i);\n        objs[s].classList.toggle(\"is-active\", on);\n        objs[s].setAttribute(\"aria-pressed\", on ? \"true\" : \"false\");\n        faces[s].classList.toggle(\"is-active\", on);\n        if (paths[s]) paths[s].classList.toggle(\"is-active\", on);\n      }\n    }\n\n    // one input's full scan → extract → resolve → hold, then advance\n    function play(i) {\n      clearTimers();\n      root.className = \"cp-uscan playing\";      // clear phase classes, keep playing\n      setActive(i);\n      void stage.offsetWidth;                    // reflow so animations restart clean\n\n      at(PH.scan,    function () { root.classList.add(\"is-scan\"); });\n      at(PH.extract, function () { root.classList.add(\"is-extract\"); });\n      at(PH.resolve, function () { root.classList.add(\"is-resolve\"); });\n      at(PH.hold,    function () { root.classList.add(\"is-hold\"); });\n      at(CYCLE,      function () { play((i + 1) % N); });\n    }\n\n    var running = false;\n    function start() {\n      if (running) return;\n      running = true;\n      at(1100, function () { play(current); });  // hold resolved face 0, then loop\n    }\n    function stop() {\n      running = false;\n      clearTimers();\n      root.className = \"cp-uscan\";                // settle resolved & static\n      root.setAttribute(\"data-active\", current);\n    }\n\n    // click any object to jump to it; loop keeps going\n    objs.forEach(function (obj, idx) {\n      obj.addEventListener(\"click\", function () {\n        if (mq.matches) { setActive(idx); return; }\n        running = true;\n        play(idx);\n      });\n    });\n\n    // test/host hook: freeze a given input fully resolved & static\n    window.cpUScanFreeze = function (i) {\n      clearTimers();\n      running = false;\n      root.className = \"cp-uscan\";\n      setActive(typeof i === \"number\" ? i : current);\n    };\n\n    var mq = window.matchMedia(\"(prefers-reduced-motion: reduce)\");\n    if (mq.matches) return;                       // reduced motion: leave face 0 static\n\n    if (\"IntersectionObserver\" in window) {\n      var io = new IntersectionObserver(function (entries) {\n        entries.forEach(function (e) { if (e.isIntersecting) start(); else stop(); });\n      }, { threshold: 0.2 });\n      io.observe(stage);\n    } else {\n      start();\n    }\n  })();\n";

export default function ScanLead() {
  const ref = useRef<HTMLDivElement>(null);
  const ran = useRef(false);
  useEffect(() => {
    if (ran.current) return;
    ran.current = true;
    try { new Function(SCRIPT)(); } catch (e) { console.error("ScanLead demo:", e); }
  }, []);
  return (
    <div ref={ref} className=""
      dangerouslySetInnerHTML={{ __html: "<style>" + CSS + "</style>" + MARKUP }} />
  );
}
